import { Box, Button, CardMedia, Dialog, DialogActions, DialogContent, DialogTitle } from '@mui/material'

interface ImagePreviewModalProps {
  isOpen: boolean
  imageUrl: string | null
  isUploading: boolean
  onClose: () => void
  onConfirm: () => void
}

const ImagePreviewModal: React.FC<ImagePreviewModalProps> = ({ isOpen, imageUrl, isUploading, onClose, onConfirm }) => {
  return (
    <Dialog open={isOpen} onClose={onClose} maxWidth="sm" fullWidth>
      <DialogTitle>이미지 미리보기</DialogTitle>
      <DialogContent>
        <Box
          display="flex"
          justifyContent="center"
          alignItems="center"
          sx={{
            minHeight: 300
          }}
        >
          {imageUrl && (
            <Box
              sx={{
                width: 200,
                height: 200,
                borderRadius: '50%',
                overflow: 'hidden',
                border: '1px solid',
                borderColor: 'divider'
              }}
            >
              <CardMedia
                component="img"
                sx={{
                  width: '100%',
                  height: '100%',
                  objectFit: 'cover'
                }}
                image={imageUrl}
                alt="미리보기 이미지"
              />
            </Box>
          )}
        </Box>
      </DialogContent>
      <DialogActions>
        <Button onClick={onClose} disabled={isUploading}>
          취소
        </Button>
        <Button onClick={onConfirm} variant="contained" disabled={isUploading} autoFocus>
          {isUploading ? '업로드 중...' : '확인'}
        </Button>
      </DialogActions>
    </Dialog>
  )
}

export default ImagePreviewModal
